Point pivot;

int cmp_double(double a, double b) {
    if (fabs(a - b) < EPS) return 0;
    return (a < b) ? -1 : 1;
}

double cross(Point a, Point b, Point c) {
    /* (b-a) x (c-a) */
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int cmp_points(const void *pa, const void *pb) {
    Point *a = (Point *)pa;
    Point *b = (Point *)pb;

    double cr = cross(pivot, *a, *b);
    if (fabs(cr) > EPS) {
        return (cr > 0) ? -1 : 1;
    }

    double da = dist2(pivot, *a);
    double db = dist2(pivot, *b);
    if (fabs(da - db) < EPS) return 0;
    return (da < db) ? -1 : 1;
}

int convex_hull(Point *p, int n, Point *h) {
    int i, m = 0;

    if (n <= 1) {
        if (n == 1) h[0] = p[0];
        return n;
    }

    int pi = 0;
    for (i = 1; i < n; i++) {
        if (cmp_double(p[i].y, p[pi].y) < 0 ||
            (cmp_double(p[i].y, p[pi].y) == 0 && cmp_double(p[i].x, p[pi].x) < 0)) {
            pi = i;
        }
    }

    Point tmp = p[0];
    p[0] = p[pi];
    p[pi] = tmp;
    pivot = p[0];

    qsort(p + 1, n - 1, sizeof(Point), cmp_points);

    h[m++] = p[0];
    h[m++] = p[1];

    for (i = 2; i < n; i++) {
        while (m >= 2 && cross(h[m - 2], h[m - 1], p[i]) <= EPS) {
            m--;
        }
        h[m++] = p[i];
    }

    return m;
}

