int convexHullSize(vector<Point> p) {
    int n = (int)p.size();
    sort(p.begin(), p.end(), cmpPoint);

    vector<Point> h(2 * n);
    int k = 0;

    // Lower hull
    for (int i = 0; i < n; ++i) {
        while (k >= 2 && cross(h[k - 2], h[k - 1], p[i]) <= EPS) k--;
        h[k++] = p[i];
    }

    // Upper hull
    int t = k + 1;
    for (int i = n - 2; i >= 0; --i) {
        while (k >= t && cross(h[k - 2], h[k - 1], p[i]) <= EPS) k--;
        h[k++] = p[i];
    }

    if (n > 1) k--; // last point equals first point
    return k;
}

