import java.util.*;

public class Main {
    static final double EPS = 1e-9;

    static class Point {
        double x, y;
        Point(double x, double y) { this.x = x; this.y = y; }
    }

    // Cross product of (b - a) and (c - a)
    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    // Distance squared between two points
    static double distSq(Point a, Point b) {
        double dx = a.x - b.x;
        double dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    // Andrew's monotone chain convex hull - returns points on hull in CCW order
    static List<Point> convexHull(Point[] pts) {
        int n = pts.length;
        if (n < 3) return Arrays.asList(pts);

        Arrays.sort(pts, (p, q) -> {
            if (Math.abs(p.x - q.x) > EPS) return Double.compare(p.x, q.x);
            return Double.compare(p.y, q.y);
        });

        List<Point> lower = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            while (lower.size() >= 2 && cross(lower.get(lower.size()-2), lower.get(lower.size()-1), pts[i]) <= EPS)
                lower.remove(lower.size()-1);
            lower.add(pts[i]);
        }

        List<Point> upper = new ArrayList<>();
        for (int i = n-1; i >= 0; i--) {
            while (upper.size() >= 2 && cross(upper.get(upper.size()-2), upper.get(upper.size()-1), pts[i]) <= EPS)
                upper.remove(upper.size()-1);
            upper.add(pts[i]);
        }

        // Remove last point of each list because it's repeated at the start of the other
        lower.remove(lower.size()-1);
        upper.remove(upper.size()-1);

        List<Point> hull = new ArrayList<>();
        hull.addAll(lower);
        hull.addAll(upper);
        return hull;
    }

    // Check if point p lies on segment ab (including endpoints)
    static boolean onSegment(Point a, Point b, Point p) {
        if (Math.abs(cross(a, b, p)) > EPS) return false;
        double dot = (p.x - a.x) * (b.x - a.x) + (p.y - a.y) * (b.y - a.y);
        if (dot < -EPS) return false;
        double lenSq = distSq(a, b);
        if (dot - lenSq > EPS) return false;
        return true;
    }

    // Count number of points on convex hull boundary
    static int countOnHull(Point[] pts, List<Point> hull) {
        int count = 0;
        int m = hull.size();
        for (Point p : pts) {
            boolean onBoundary = false;
            for (int i = 0; i < m; i++) {
                Point a = hull.get(i);
                Point b = hull.get((i+1) % m);
                if (onSegment(a, b, p)) {
                    onBoundary = true;
                    break;
                }
            }
            if (onBoundary) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int n = sc.nextInt();
            if (n == 0) break;
            Point[] pts = new Point[n];
            for (int i = 0; i < n; i++) {
                double x = sc.nextDouble();
                double y = sc.nextDouble();
                pts[i] = new Point(x, y);
            }
            List<Point> hull = convexHull(pts);
            int onHull = countOnHull(pts, hull);
            System.out.println(n - onHull);
        }
        sc.close();
    }
}

