        return (A[0] - O[0]) * (B[1] - O[1]) - (A[1] - O[1]) * (B[0] - O[0]);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            double[][] pts = new double[n][2];
            for (int i = 0; i < n; i++) {
                pts[i][0] = sc.nextDouble();
                pts[i][1] = sc.nextDouble();
            }

            // Compute convex hull
            double[][] sorted = pts.clone();
            Arrays.sort(sorted, (a, b) -> a[0] != b[0] ? Double.compare(a[0], b[0]) : Double.compare(a[1], b[1]));

            int m = sorted.length;
            double[][] hull = new double[2 * m][2];
            int k = 0;

            // Lower hull
            for (int i = 0; i < m; i++) {
                while (k >= 2 && cross(hull[k-2], hull[k-1], sorted[i]) <= 0) k--;
                hull[k++] = sorted[i];
            }
            // Upper hull
            for (int i = m - 2, t = k + 1; i >= 0; i--) {
                while (k >= t && cross(hull[k-2], hull[k-1], sorted[i]) <= 0) k--;
                hull[k++] = sorted[i];
            }

            // hull[0..k-2] are the convex hull vertices (k-1 unique points)
            double[][] hullPts = Arrays.copyOf(hull, k - 1);

            // Count points on convex hull (vertices + on edges)
            int onHull = 0;
            for (double[] p : pts) {
                if (isOnHull(p, hullPts)) onHull++;
            }

            System.out.println(n - onHull);
        }
