    static boolean isOnHull(double[] p, double[][] hull) {
        int m = hull.length;
        for (int i = 0; i < m; i++) {
            double[] a = hull[i];
            double[] b = hull[(i + 1) % m];
            // Check if p is on segment a-b
            double cp = cross(a, b, p);
            if (Math.abs(cp) < 1e-9) {
                // Collinear, check if between a and b
                double minX = Math.min(a[0], b[0]);
                double maxX = Math.max(a[0], b[0]);
                double minY = Math.min(a[1], b[1]);
                double maxY = Math.max(a[1], b[1]);
                if (p[0] >= minX - 1e-9 && p[0] <= maxX + 1e-9 &&
                    p[1] >= minY - 1e-9 && p[1] <= maxY + 1e-9) {
                    return true;
                }
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }
    }

    static class Point implements Comparable<Point> {
        double x, y;

        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }

        @Override
        public int compareTo(Point o) {
            int cx = Double.compare(this.x, o.x);
            if (cx != 0) return cx;
            return Double.compare(this.y, o.y);
        }
    }

    static final double EPS = 1e-10;

    static double cross(Point a, Point b, Point c) {
        return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
    }

    static List<Point> convexHull(Point[] pts) {
        int n = pts.length;
        Arrays.sort(pts);
        if (n <= 1) return Arrays.asList(pts);

        List<Point> lower = new ArrayList<>();
        for (Point p : pts) {
            while (lower.size() >= 2) {
                int m = lower.size();
                if (cross(lower.get(m - 2), lower.get(m - 1), p) <= EPS) {
                    lower.remove(m - 1);
                } else break;
            }
            lower.add(p);
        }

        List<Point> upper = new ArrayList<>();
        for (int i = n - 1; i >= 0; i--) {
            Point p = pts[i];
            while (upper.size() >= 2) {
                int m = upper.size();
                if (cross(upper.get(m - 2), upper.get(m - 1), p) <= EPS) {
                    upper.remove(m - 1);
                } else break;
            }
            upper.add(p);
        }

        lower.remove(lower.size() - 1);
        upper.remove(upper.size() - 1);
        lower.addAll(upper);
        return lower;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String s = fs.next();
            if (s == null) break;
            int n = Integer.parseInt(s);
            if (n == 0) break;

            Point[] pts = new Point[n];
            for (int i = 0; i < n; i++) {
                double x = fs.nextDouble();
                double y = fs.nextDouble();
                pts[i] = new Point(x, y);
            }

            List<Point> hull = convexHull(pts.clone());
            int touched = hull.size();
            int notTouched = n - touched;
            out.append(notTouched).append('\n');
        }

        System.out.print(out.toString());
    }
}
